356: /** Removes redundant <dir>/.. elements in the path. Returns an empty path if the 
357: * specified path has a broken number of directories for its number of ..s */
358: std::string Path_Compact( const std::string & sRawPath, char slash )
359: {
360: 	if( slash == 0 )
361: 		slash = Path_GetSlash();
362: 
363: 	std::string sPath = Path_FixSlashes( sRawPath, slash );
364: 	std::string sSlashString( 1, slash );
365: 
366: 	// strip out all /./
367: 	for( std::string::size_type i = 0; (i + 3) < sPath.length();  )
368: 	{
369: 		if( sPath[ i ] == slash && sPath[ i+1 ] == '.' && sPath[ i+2 ] == slash )
370: 		{
371: 			sPath.replace( i, 3, sSlashString );
372: 		}
373: 		else
374: 		{
375: 			++i;
376: 		}
377: 	}
378: 
379: 
380: 	// get rid of trailing /. but leave the path separator
381: 	if( sPath.length() > 2 )
382: 	{
383: 		std::string::size_type len = sPath.length();
384: 		if( sPath[ len-1 ] == '.'  && sPath[ len-2 ] == slash )
385: 		{
386: 			sPath.pop_back();
387: 			//Not sure why the following line of code was used for a while.  It causes problems with strlen.
388: 			//sPath[len-1] = 0;  // for now, at least 
389: 		}
390: 	}
391: 
392: 	// get rid of leading ./ 
393: 	if( sPath.length() > 2 )
394: 	{
395: 		if( sPath[ 0 ] == '.'  && sPath[ 1 ] == slash )
396: 		{
397: 			sPath.replace( 0, 2, "" );
398: 		}
399: 	}
400: 
401: 	// each time we encounter .. back up until we've found the previous directory name
402: 	// then get rid of both
403: 	std::string::size_type i = 0;
404: 	while( i < sPath.length() )
405: 	{
406: 		if( i > 0 && sPath.length() - i >= 2 
407: 			&& sPath[i] == '.'
408: 			&& sPath[i+1] == '.'
409: 			&& ( i + 2 == sPath.length() || sPath[ i+2 ] == slash )
410: 			&& sPath[ i-1 ] == slash )
411: 		{
412: 			// check if we've hit the start of the string and have a bogus path
413: 			if( i == 1 )
414: 				return "";
415: 			
416: 			// find the separator before i-1
417: 			std::string::size_type iDirStart = i-2;
418: 			while( iDirStart > 0 && sPath[ iDirStart - 1 ] != slash )
419: 				--iDirStart;
420: 
421: 			// remove everything from iDirStart to i+2
422: 			sPath.replace( iDirStart, (i - iDirStart) + 3, "" );
423: 
424: 			// start over
425: 			i = 0;
426: 		}
427: 		else
428: 		{
429: 			++i;
430: 		}
431: 	}
432: 
433: 	return sPath;
434: }
