24: //-----------------------------------------------------------------------------
25: // Purpose: utility function to create dirs & subdirs
26: //-----------------------------------------------------------------------------
27: bool BCreateDirectoryRecursive( const char *pchPath )
28: {
29: 	// Does it already exist?
30: 	if ( Path_IsDirectory( pchPath ) )
31: 		return true;
32: 
33: 	// copy the path into something we can munge
34: 	int len = (int)strlen( pchPath );
35: 	char *path = (char *)malloc( len + 1 );
36: 	strcpy( path, pchPath );
37: 
38: 	// Walk backwards to first non-existing dir that we find
39: 	char *s = path + len - 1;
40: 
41: 	const char slash = Path_GetSlash();
42: 	while ( s > path )
43: 	{
44: 		if ( *s == slash )
45: 		{
46: 			*s = '\0';
47: 			bool bExists = Path_IsDirectory( path );
48: 			*s = slash;
49: 
50: 			if ( bExists )
51: 			{
52: 				++s;
53: 				break;
54: 			}
55: 		}
56: 		--s;
57: 	}
58: 
59: 	// and then move forwards from there
60: 
61: 	while ( *s )
62: 	{
63: 		if ( *s == slash )
64: 		{
65: 			*s = '\0';
66: 			BCreateDirectory( path );
67: 			*s = slash;
68: 		}
69: 		s++;
70: 	}
71: 
72: 	bool bRetVal = BCreateDirectory( path );
73: 	free( path );
74: 	return bRetVal;
75: }
