442: static char selectBuf[ PATH_MAX ];
443: 
444: #if defined( OSX ) && !defined( __MAC_10_8 )
445: static int FileSelect( direntBig_t *ent )
446: #elif defined( LINUX ) || defined( OSX )
447: static int FileSelect( const direntBig_t *ent )
448: #else
449: #error
450: #endif
451: {
452: 	const char *mask = selectBuf;
453: 	const char *name = ent->d_name;
454: 
455: 	return FileSelect( name, mask );
456: }
