512: int FillDataStruct( _finddata_t *dat )
513: {
514: 	statBig_t fileStat;
515: 
516: 	if ( dat->curName >= dat->numNames )
517: 		return -1;
518: 
519: 	strncpy( dat->name, dat->namelist[ dat->curName ]->d_name, sizeof( dat->name ) );
520: 	char szFullPath[ MAX_PATH ];
521: 	int nWriteSize = snprintf( szFullPath, sizeof( szFullPath ), "%s%c%s", dat->dirBase, Path_GetSlash(), dat->name );
522: 	if ( nWriteSize >= sizeof( szFullPath ) )
523: 	{
524: 		Log( LogError, "File path truncated\n" );
525: 	}
526: 	if ( statBig( szFullPath, &fileStat ) == 0 )
527: 	{
528: 		dat->attrib = fileStat.st_mode;
529: 		dat->size = fileStat.st_size;
530: 		dat->time_write = fileStat.st_mtime;
531: 		dat->time_create = fileStat.st_ctime;
532: 	}
533: 	else
534: 	{
535: 		dat->attrib = 0;
536: 		dat->size = 0;
537: 		dat->time_write = 0;
538: 		dat->time_create = 0;
539: 	}
540: 	free( dat->namelist[ dat->curName ] );
541: 	dat->namelist[ dat->curName ] = NULL;
542: 	dat->curName++;
543: 	return 1;
544: }
