546: int _findfirst( const char *fileName, _finddata_t *dat )
547: {
548: 	char nameStore[ MAX_PATH ];
549: 	char *dir = NULL;
550: 	int n, iret = -1;
551: 
552: 	strncpy( nameStore, fileName, sizeof( nameStore ) );
553: 
554: 	if ( strrchr( nameStore, '/' ) )
555: 	{
556: 		dir = nameStore;
557: 		while ( strrchr( dir, '/' ) )
558: 		{
559: 			statBig_t dirChk;
560: 
561: 			// zero this with the dir name
562: 			dir = strrchr( nameStore, '/' );
563: 			*dir = '\0';
564: 			if ( dir == nameStore )
565: 			{
566: 				strcpy( nameStore, "/" ); // C++11 would prefer no `dir = "/";`
567: 			}
568: 			else
569: 			{
570: 				dir = nameStore;
571: 			}
572: 
573: 			if ( statBig( dir, &dirChk ) == 0 && S_ISDIR( dirChk.st_mode ) )
574: 			{
575: 				break;
576: 			}
577: 		}
578: 	}
579: 	else
580: 	{
581: 		// couldn't find a dir separator...
582: 		return -1;
583: 	}
584: 
585: 	if ( strlen( dir ) > 0 )
586: 	{
587: 		if ( strlen( dir ) == 1 )
588: 			strncpy( selectBuf, fileName + 1, sizeof( selectBuf ) );
589: 		else
590: 			strncpy( selectBuf, fileName + strlen( dir ) + 1, sizeof( selectBuf ) );
591: 
592: 		n = scandirBig( dir, &dat->namelist, FileSelect, alphasortBig );
593: 		if ( n < 0 )
594: 		{
595: 			// silently return, nothing interesting
596: 		}
597: 		else
598: 		{
599: 			dat->curName = 0;
600: 			dat->numNames = n; // n is the number of matches
601: 			strncpy( dat->dirBase, dir, sizeof( dat->dirBase ) );
602: 			iret = FillDataStruct( dat );
603: 			if ( iret < 0 )
604: 			{
605: 				free( dat->namelist );
606: 				dat->namelist = NULL;
607: 				dat->curName = 0;
608: 				dat->numNames = 0;
609: 			}
610: 		}
